const test = require('node:test');
const assert = require('node:assert/strict');

const { slugify } = require('./slugify');

test('converts a normal title with spaces', () => {
  assert.equal(slugify('hello world'), 'hello-world');
});

test('lowercases mixed case input', () => {
  assert.equal(slugify('Hello World'), 'hello-world');
});

test('replaces punctuation with hyphens', () => {
  assert.equal(slugify('Hello, World! (again)'), 'hello-world-again');
});

test('trims leading and trailing whitespace', () => {
  assert.equal(slugify('   Spaced Out   '), 'spaced-out');
});

test('collapses consecutive separators into a single hyphen', () => {
  assert.equal(slugify('a --  b___c'), 'a-b-c');
});

test('strips diacritics', () => {
  assert.equal(slugify('Crème Brûlée'), 'creme-brulee');
});

test('returns an empty string for an empty input', () => {
  assert.equal(slugify(''), '');
});

test('returns an empty string for all-punctuation input', () => {
  assert.equal(slugify('!!! ---'), '');
});

test('returns an empty string for nullish or non-string input', () => {
  assert.equal(slugify(null), '');
  assert.equal(slugify(undefined), '');
  assert.equal(slugify(42), '');
  assert.equal(slugify({}), '');
});

const ELLIPSIS = '...';

function truncate(text, n) {
  if (typeof text !== 'string') {
    return '';
  }
  if (typeof n !== 'number' || Number.isNaN(n) || n <= 0) {
    return '';
  }
  if (text.length <= n) {
    return text;
  }
  // Too little room for the ellipsis to be meaningful, so hard cut instead.
  if (n < ELLIPSIS.length) {
    return text.slice(0, n);
  }
  return text.slice(0, n - ELLIPSIS.length) + ELLIPSIS;
}

module.exports = { truncate };

const test = require('node:test');
const assert = require('node:assert/strict');

const { truncate } = require('./truncate');

test('returns text unchanged when shorter than n', () => {
  assert.equal(truncate('abc', 10), 'abc');
});

test('returns text unchanged when exactly n characters', () => {
  assert.equal(truncate('abcde', 5), 'abcde');
});

test('truncates to at most n characters including the ellipsis', () => {
  const result = truncate('abcdefghij', 5);
  assert.equal(result, 'ab...');
  assert.equal(result.length, 5);
  assert.ok(result.endsWith('...'));
});

test('hard cuts when n is smaller than the ellipsis length', () => {
  assert.equal(truncate('abcdefghij', 2), 'ab');
  assert.equal(truncate('abcdefghij', 1), 'a');
});

test('returns an empty string for n of 0 or negative', () => {
  assert.equal(truncate('abcdefghij', 0), '');
  assert.equal(truncate('abcdefghij', -3), '');
});

test('returns an empty string for nullish or non-string text', () => {
  assert.equal(truncate(null, 5), '');
  assert.equal(truncate(undefined, 5), '');
  assert.equal(truncate(12345678, 5), '');
});

